mapper.select:
SELECT tenant_id AS tenantId, stat_date AS statDate, provider, model_name AS modelName, call_count AS callCount, input_tokens AS inputTokens, output_tokens AS outputTokens, cached_tokens AS cachedTokens, total_tokens AS totalTokens, model_segment_count AS modelSegmentCount, settled_segment_count AS settledSegmentCount, unsettled_segment_count AS unsettledSegmentCount, CASE WHEN settled_segment_count = model_segment_count AND model_segment_count > 0 THEN 'COMPLETE' WHEN settled_segment_count = 0 THEN 'UNAVAILABLE' ELSE 'PARTIAL' END AS pricingStatus, amount, currency, source_max_call_log_id AS sourceMaxCallLogId FROM cw_tenant_usage_daily WHERE stat_date = #{statDate}
AND tenant_id = #{tenantId}
ORDER BY tenant_id, provider, model_name, currency

SELECT COALESCE(SUM(amount), 0)
FROM cw_tenant_usage_daily
WHERE tenant_id = #{tenantId}
  AND stat_date BETWEEN #{from} AND #{to}
  AND currency = 'CNY'
